    funders: usize,
}

#[derive(Serialize, JsonSchema)]
struct DeclarationResolutionResponse {
    ingestion_key: IngestionKey,
    /// Absolute resolved/declarations artifact directory.
    path: PathBuf,
    /// Source funder observations, including unresolved names.
    observations: usize,
    /// Original funding occurrences, counted once.
    payments: usize,
    /// Retained pair decisions between funder observations.
use std::future::Future;

use schemars::{JsonSchema, Schema, generate::SchemaSettings};
use serde::Serialize;
use strum::IntoEnumIterator;

use super::{CliSuccess, response::ErrorResponse};
use crate::domain::models::entity_ingestion::DeclarationIngestionStage;

fn schema<T: JsonSchema>() -> Schema {
    SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator()
        .into_root_schema_for::<T>()
}

trait ResponseSchema {
    fn schema() -> Schema;
}

impl<T: Serialize + JsonSchema, E> ResponseSchema for Result<CliSuccess<T>, E> {
    fn schema() -> Schema {
        schema::<T>()
    }
}

pub(super) trait HandlerSchema<Args> {
    fn response_schema(self) -> Schema;
}

macro_rules! handler_schema {
    ($($arg:ident),*) => {
        impl<F, Fut, $($arg,)*> HandlerSchema<($($arg,)*)> for F
        where
            F: FnOnce($($arg),*) -> Fut,
            Fut: Future,
            Fut::Output: ResponseSchema,
        {
            fn response_schema(self) -> Schema {
                <Fut::Output as ResponseSchema>::schema()
            }
        }
    };
}

handler_schema!();
handler_schema!(A);
handler_schema!(A, B);
handler_schema!(A, B, C);

fn section(label: &str, schema: &Schema) -> String {
    format!(
        "{label}\n{}\n",
        serde_json::to_string_pretty(schema).expect("JSON schema serializes")
    )
}

fn failure() -> String {
    format!(
        "Success: one JSON document on stdout, exit 0.\nCommand failure: one JSON document on stderr, exit 1.\nClap argument errors and help use Clap's text output.\nSchemas use JSON Schema draft 2020-12.\n\n{}",
        section("Failure JSON schema:", &schema::<ErrorResponse>())
    )
}

pub(super) fn single<Args>(handler: impl HandlerSchema<Args>) -> String {
    format!(
        "{}\n{}",
        section("Success JSON schema:", &handler.response_schema()),
        failure()
    )
}

pub(super) fn declarations() -> String {
    let mut help = String::new();
    for stage in DeclarationIngestionStage::iter() {
        let mut schema = match stage {
            DeclarationIngestionStage::Fetch => super::fetch_declarations.response_schema(),
            DeclarationIngestionStage::Clean => super::clean_declarations.response_schema(),
            DeclarationIngestionStage::Resolve => super::resolve_declarations.response_schema(),
            DeclarationIngestionStage::Load => super::load_declarations.response_schema(),
        };
        if stage == DeclarationIngestionStage::Fetch {
            schema
                .as_object_mut()
                .expect("response schema is an object")["properties"]["stage"]["const"] =
                serde_json::to_value(&stage).expect("stage serializes");
        }
        let label = serde_json::to_value(&stage).expect("stage serializes");
        help.push_str(&section(
            &format!(
                "Success JSON schema ({}):",
                label.as_str().expect("stage is a string")
            ),
            &schema,
        ));
        help.push('\n');
    }
    help.push_str(&failure());
    help
}
//! JSON command results and their conversion to CLI output.

use schemars::JsonSchema;
use serde::Serialize;
use std::{
    io::{self, Write},
    process::ExitCode,
};

/// Generic JSON success response.
///
/// Payloads must expose their JSON schema as well as their serialization.
///
/// ```compile_fail
/// use exposed::inbound::cli::CliSuccess;
/// #[derive(serde::Serialize)]
/// struct Undocumented { count: usize }
/// let _ = CliSuccess::new(Undocumented { count: 1 });
/// ```
pub struct CliSuccess<S: Serialize + JsonSchema> {
    response: S,
}

impl<S: Serialize + JsonSchema> CliSuccess<S> {
    /// Creates a success response with a typed payload.
    pub const fn new(response: S) -> Self {
        Self { response }
    }
}

/// A serialized success or the original command failure.
pub struct Response(anyhow::Result<Vec<u8>>);

#[derive(Serialize, JsonSchema)]
pub(super) struct ErrorResponse {
    error: ErrorMessage,
}

#[derive(Serialize, JsonSchema)]
struct ErrorMessage {
    message: String,
}

impl Response {
    /// Writes one JSON document to stdout on success or stderr on failure.
    ///
    /// # Errors
    /// Returns an error if the selected output writer fails.
    pub fn write_to(self, mut stdout: impl Write, mut stderr: impl Write) -> io::Result<ExitCode> {
        let (mut bytes, writer, code): (_, &mut dyn Write, _) = match self.0 {
            Ok(bytes) => (bytes, &mut stdout, ExitCode::SUCCESS),
            Err(error) => {
                let payload = ErrorResponse {
                    error: ErrorMessage {
                        message: format!("{error:#}"),
                    },
                };
                let bytes = serde_json::to_vec(&payload).map_err(io::Error::other)?;
                (bytes, &mut stderr, ExitCode::FAILURE)
            }
        };
        bytes.push(b'\n');
        writer.write_all(&bytes)?;
        Ok(code)
    }
}

/// Converts a typed command result to a CLI response.
///
/// Wrap success payloads in [`CliSuccess`] before converting them.
///
/// ```compile_fail
/// use exposed::inbound::cli::IntoResponse;
/// "arbitrary text".into_response();
/// ```
pub trait IntoResponse {
    /// Converts this value to a response for the CLI boundary.
    fn into_response(self) -> Response;
}

impl IntoResponse for Response {
    fn into_response(self) -> Response {
        self
    }
}

impl<S: Serialize + JsonSchema> IntoResponse for CliSuccess<S> {
    fn into_response(self) -> Response {
        Response(serde_json::to_vec(&self.response).map_err(Into::into))
    }
}

impl<T, E> IntoResponse for Result<T, E>
where
    T: IntoResponse,
    E: Into<anyhow::Error>,
{
    fn into_response(self) -> Response {
        match self {
            Ok(value) => value.into_response(),
            Err(error) => Response(Err(error.into())),
        }
    }
}
